def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    last_m, last_o = history[-1]
    if n == 1:
        return 'C' if last_o == 'C' else 'D'
    if all(o == 'D' for _, o in history):
        return 'D'
    recent = history[-5:] if n >= 5 else history
    opp_def_recent = sum(1 for _, o in recent if o == 'D')
    my_def_recent = sum(1 for m, _ in recent if m == 'D')
    if len(recent) >= 5 and opp_def_recent >= 4:
        return 'D'
    if n >= 10:
        last10 = history[-10:]
        opp_def_10 = sum(1 for _, o in last10 if o == 'D')
        if opp_def_10 == 0 and n < 90:
            if my_def_recent == 0 and rng.random() < 0.1:
                return 'D'
    if last_o == 'C':
        if last_m == 'D':
            if opp_def_recent >= 2:
                return 'C'
            return 'D'
        else:
            return 'C'
    else:
        if last_m == 'C':
            if n >= 2 and history[-2][0] == 'D':
                return 'C'
            if opp_def_recent >= 4:
                return 'D'
            return 'C'
        else:
            if opp_def_recent >= 4:
                return 'D'
            return 'C'
